// Shrink the text until the directions fit on the card (no hidden overflow).
function fitCards(root, start) {
  const cards = [...root.querySelectorAll(".pc")];
  const card = cards[0], steps = card.querySelector(".pc-steps");
  const over = () =&gt;
    card.scrollHeight &gt; card.clientHeight + 1 ||
    steps.scrollHeight &gt; steps.clientHeight + 1 ||
    steps.scrollWidth &gt; steps.clientWidth + 1;
  let size = start;
  const apply = () =&gt; cards.forEach((c) =&gt; (c.style.fontSize = `${size}pt`));
  apply();
  while (over() && size &gt; 5) {
    size -= 0.25;
    apply();
  }
  return size;
}

