      body { margin: 0; }
      .sheet { display: grid; width: 7.9in;
               grid-template-columns: repeat(${layout.cols}, ${layout.w}in);
               grid-template-rows: repeat(${layout.rows}, ${layout.h}in); }
    &lt;/style&gt;&lt;/head&gt;
    &lt;body&gt;&lt;div class="sheet"&gt;${cardHtml(f, layout).repeat(layout.n)}&lt;/div&gt;
    &lt;script&gt;${fitCards.toString()}
      window.onload = () =&gt; { fitCards(document, ${layout.font}); window.print(); };
    &lt;\/script&gt;&lt;/body&gt;&lt;/html&gt;`;
  const w = window.open("", "_blank");
  w.document.write(page);
  w.document.close();
}

// The card as a picture, to keep on the phone: the preview, each word drawn
// where the browser put it, at 4x (about 380 dpi). No dashed cut line.
async function cardImage(card) {
  const k = 4, box = card.getBoundingClientRect();
  const canvas = Object.assign(document.createElement("canvas"),
    {width: Math.round(box.width * k), height: Math.round(box.height * k)});
  const ctx = canvas.getContext("2d");
  ctx.scale(k, k);
  ctx.translate(-box.left, -box.top);
  ctx.fillStyle = "#fff";
  ctx.fillRect(box.left, box.top, box.width, box.height);
  for (const el of card.querySelectorAll("*")) { // the rules under the name and over the key
    const cs = getComputedStyle(el), r = el.getBoundingClientRect();
    for (const side of ["Top", "Bottom"]) {
      const w = parseFloat(cs[`border${side}Width`]);
      if (!w || cs[`border${side}Style`] === "none") continue;
      ctx.fillStyle = cs[`border${side}Color`];
      ctx.fillRect(r.left, side === "Top" ? r.top : r.bottom - w, r.width, w);
    }
  }
  for (const svg of card.querySelectorAll("svg")) { // the outline, drawn at full size
    const r = svg.getBoundingClientRect(), img = new Image(), copy = svg.cloneNode(true);
    copy.setAttribute("width", r.width * k);
    copy.setAttribute("height", r.height * k);
    copy.style.fontFamily = getComputedStyle(svg).fontFamily; // an image doesn't inherit it
    await new Promise((resolve, reject) =&gt; {
      img.onload = resolve;
      img.onerror = reject;
      img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(new XMLSerializer().serializeToString(copy))}`;
    });
    ctx.drawImage(img, r.left, r.top, r.width, r.height);
  }
  const words = document.createTreeWalker(card, NodeFilter.SHOW_TEXT), range = document.createRange();
  ctx.textBaseline = "middle";
  for (let node; (node = words.nextNode()); ) {
    if (node.parentElement.closest("svg")) continue;
    const cs = getComputedStyle(node.parentElement);
    ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
    ctx.fillStyle = cs.color;
    for (const m of node.data.matchAll(/\S+/g)) {
      range.setStart(node, m.index);
      range.setEnd(node, m.index + m[0].length);
      const r = range.getBoundingClientRect();
      if (r.width && r.bottom &lt;= box.bottom && r.right &lt;= box.right) {
        ctx.fillText(m[0], r.left, (r.top + r.bottom) / 2);
      }
    }
  }
  return new Promise((resolve) =&gt; canvas.toBlob(resolve, "image/png"));
}

function cardImageButton(f) {
  const button = html`&lt;button class="btn btn-quarto" type="button"
    title="The card as a picture, to keep on your phone"&gt;Card image&lt;/button&gt;`;
  button.onclick = async () =&gt; {
    const card = cardPreview.querySelector(".pc");
    saveImage(await cardImage(card), `psp-${f.properties.id}-card.png`, f.properties.name);
  };
  return button;
}

